L49_1.m_Talk_TWN = L50_1
L50_1 = "\224\184\156\224\184\161\224\184\170\224\184\173\224\184\153\224\185\128\224\184\130\224\184\178\224\184\167\224\185\136\224\184\178\224\185\132\224\184\161\224\185\136\224\184\149\224\185\137\224\184\173\224\184\135\224\185\132\224\184\155\224\184\155\224\184\129\224\184\155\224\185\137\224\184\173\224\184\135\224\185\131\224\184\132\224\184\163\224\184\153\224\184\173\224\184\129\224\184\136\224\184\178\224\184\129\224\184\149\224\184\177\224\184\167\224\185\128\224\184\173\224\184\135 \224\185\129\224\184\149\224\185\136\224\185\128\224\184\130\224\184\178\224\184\129\224\185\135\224\185\128\224\184\171\224\185\135\224\184\153\224\185\129\224\184\129\224\185\136\224\184\132\224\184\153\224\184\173\224\184\183\224\185\136\224\184\153\224\185\128\224\184\155\224\185\135\224\184\153\224\184\153\224\184\180\224\184\170\224\184\177\224\184\162\224\184\153\224\185\136\224\184\176\224\184\132\224\184\163\224\184\177\224\184\154 \224\184\156\224\184\161\224\184\167\224\185\136\224\184\178\224\185\128\224\184\130\224\184\178\224\184\129\224\185\135\224\184\132\224\184\135\224\185\128\224\184\173\224\184\178\224\184\161\224\184\177\224\184\153\224\185\132\224\184\155\224\185\131\224\184\138\224\185\137\224\185\128\224\184\158\224\184\183\224\185\136\224\184\173\224\184\132\224\184\153\224\184\173\224\184\183\224\185\136\224\184\153\224\185\129\224\184\151\224\184\153"
L49_1.m_Talk_THA = L50_1
L50_1 = "Ta \196\145\195\163 d\225\186\161y n\195\179 r\225\186\177ng kh\195\180ng \196\145\198\176\225\187\163c b\225\186\163o v\225\187\135 ai kh\195\161c ngo\195\160i ch\195\173nh b\225\186\163n th\195\162n m\195\172nh. Nh\198\176ng v\225\187\155i b\225\186\163n t\195\173nh v\225\187\139 tha, ta tin l\195\160 n\195\179 v\225\186\171n \196\145ang s\225\187\173 d\225\187\165ng t\195\160i n\196\131ng c\225\187\167a m\195\172nh \196\145\225\187\131 c\225\187\169u ng\198\176\225\187\157i kh\195\161c."
L49_1.m_Talk_VTN = L50_1
L50_1 = "\230\136\145\229\145\138\232\175\137\228\187\150\229\173\166\231\174\173\229\143\170\230\152\175\228\184\186\228\186\134\228\191\157\230\138\164\232\135\170\229\183\177\239\188\140\228\189\134\228\190\157\231\133\167\233\130\163\229\173\169\229\173\144\231\154\132\230\128\167\230\160\188\239\188\140\228\184\128\229\174\154\228\188\154\231\148\168\233\130\163\228\184\170\229\138\155\233\135\143\230\157\165\228\191\157\230\138\164\229\136\171\228\186\186\231\154\132\229\144\167\227\128\130"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Ich habe ihm beigebracht, niemanden au\195\159er sich selbst zu besch\195\188tzen. Aber aufgrund seiner altruistischen Natur glaube ich, dass er seine Kr\195\164fte stattdessen f\195\188r andere verwendet hat."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Je voulais seulement qu'il apprenne \195\160 se prot\195\169ger. Mais de par sa nature altruiste, je crois qu'il met surtout ses forces au service des autres."
